const settings = require('./settings')
const command = require('./passwordCommand')
const matchesStoredKey = require('./matchesStoredKey')

function failure (message = '1Password CLI could not read the private key; check sign-in and vault permissions') {
  return Object.assign(new Error(message), { code: '1PASSWORD_FAILED' })
}

function location (value) {
  if (!value) return null
  const parts = String(value).split('|')
  const [account, reference] = parts
  if (parts.length !== 2 || !/^[a-z0-9]{26}$/i.test(account) || !/^op:\/\/[a-z0-9]{26}\/[a-z0-9]{26}\/(?:private_key|password)$/i.test(reference)) {
    throw failure('invalid 1Password private-key reference in dotenvx settings')
  }
  return ['read', reference, '--no-newline', `--account=${account}`]
}

function verified (publicKey, value) {
  if (matchesStoredKey(publicKey, value)) return { [publicKey]: value }
  throw failure('1Password private key does not match the .env public key')
}

module.exports = function onepassword (options = {}) {
  const env = () => options.processEnv || process.env
  const disabled = () => options.no1Password === true || env().DOTENVX_NO_1PASSWORD === 'true'
  return {
    async get (publicKey) {
      if (disabled()) return {}
      const args = location(await settings.get(`DOTENVX_ONEPASSWORD_${publicKey}`, env()))
      if (!args) return {}
      return verified(publicKey, await command('op', env(), failure).get(args))
    },
    getSync (publicKey) {
      if (disabled()) return {}
      const args = location(settings.getSync(`DOTENVX_ONEPASSWORD_${publicKey}`, env()))
      if (!args) return {}
      return verified(publicKey, command('op', env(), failure).getSync(args))
    }
  }
}
